                || edge == RectangleEdge.RIGHT) {
            x = cursor;
            y = dataArea.getMaxY();
            arrow = this.downArrow; 
        }

        // draw the arrow...
        AffineTransform transformer = new AffineTransform();
        transformer.setToTranslation(x, y);
        Shape shape = transformer.createTransformedShape(arrow);
        g2.fill(shape);
        g2.draw(shape);
    }

}

protected void drawAxisLine(Graphics2D g2, double cursor,
                            Rectangle2D dataArea, RectangleEdge edge) {
    Line2D axisLine = null;
    if (edge == RectangleEdge.TOP) {
        axisLine = new Line2D.Double(dataArea.getX(), cursor, 
                dataArea.getMaxX(), cursor);  
    }
    else if (edge == RectangleEdge.BOTTOM) {
        axisLine = new Line2D.Double(dataArea.getX(), cursor, 
                dataArea.getMaxX(), cursor);  
    }
    else if (edge == RectangleEdge.LEFT) {
        axisLine = new Line2D.Double(cursor, dataArea.getY(), cursor, 
                dataArea.getMaxY());  
    }
    else if (edge == RectangleEdge.RIGHT) {
        axisLine = new Line2D.Double(cursor, dataArea.getY(), cursor, 
                dataArea.getMaxY());  
    }
    g2.setPaint(getAxisLinePaint());
    g2.setStroke(getAxisLineStroke());
    g2.draw(axisLine);

    boolean drawUpOrRight = false;  
    boolean drawDownOrLeft = false;
    if (this.positiveArrowVisible) {
        if (this.inverted) {
            drawDownOrLeft = true;   
        }
        if (true) {
            drawUpOrRight = true;   
        }
    }
    if (this.negativeArrowVisible) {
        if (this.inverted) {
            drawUpOrRight = true;   
        }
        else {
            drawDownOrLeft = true;   
        }
    }
    if (drawUpOrRight) {
        double x = 0.0;
        double y = 0.0;
        Shape arrow = null;
        if (edge == RectangleEdge.TOP || edge == RectangleEdge.BOTTOM) {
            x = dataArea.getMaxX();
            y = cursor;
            arrow = this.rightArrow; 
        }
        else if (edge == RectangleEdge.LEFT 
                || edge == RectangleEdge.RIGHT) {
            x = cursor;
            y = dataArea.getMinY();
            arrow = this.upArrow; 
        }

        // draw the arrow...
        AffineTransform transformer = new AffineTransform();
        transformer.setToTranslation(x, y);
        Shape shape = transformer.createTransformedShape(arrow);
        g2.fill(shape);
        g2.draw(shape);
    }

    if (drawDownOrLeft) {
        double x = 0.0;
        double y = 0.0;
        Shape arrow = null;
        if (edge == RectangleEdge.TOP || edge == RectangleEdge.BOTTOM) {
            x = dataArea.getMinX();
            y = cursor;
            arrow = this.leftArrow; 
        }
        else if (edge == RectangleEdge.LEFT 
                || edge == RectangleEdge.RIGHT) {
            x = cursor;
            y = dataArea.getMaxY();
            arrow = this.downArrow; 
        }

        // draw the arrow...
        AffineTransform transformer = new AffineTransform();
        transformer.setToTranslation(x, y);
        Shape shape = transformer.createTransformedShape(arrow);
        g2.fill(shape);
        g2.draw(shape);
    }

}
